--MySQl
DROP TABLE IF EXISTS CHB_CONSIGNOR_DETAIL_SUB;
CREATE TABLE CHB_CONSIGNOR_DETAIL_SUB (
    REGIST_SEQNO VARCHAR(36) NOT NULL COMMENT '主键uuid',
    LAST_HOLD_DAY DATE NOT NULL COMMENT '最后持仓日期',
    PROD_ID VARCHAR(50) NOT NULL COMMENT '产品代码',
    PROD_NAME VARCHAR(100) DEFAULT NULL COMMENT '产品名称',
    PRD_REGIST_CODE VARCHAR(50) DEFAULT NULL COMMENT '产品登记编码',
    MANAGER VARCHAR(100) DEFAULT NULL COMMENT '管理人',
    PROD_TYPE VARCHAR(4) DEFAULT NULL COMMENT '产品类型',
    PROD_INVEST_TYPE VARCHAR(2) DEFAULT NULL COMMENT '产品投资性质',
    RAISE_TYPE VARCHAR(2) DEFAULT NULL COMMENT '募集方式',
    TERMID VARCHAR(20) DEFAULT NULL COMMENT '期限（年）',
    PROD_SCALE DECIMAL(30,8) DEFAULT NULL COMMENT '产品规模（元）',
    INBANK_BONDMARK_HOLD_DENOMINA DECIMAL(30,8) DEFAULT NULL COMMENT '银行间债券市场持仓面额',
    INBANK_BONDMARK_HOLD_RATIO DECIMAL(30,8) DEFAULT NULL COMMENT '银行间债券市场持仓占比',
    HOLDER_NAME VARCHAR(50) DEFAULT NULL COMMENT '投资人名称',
    HOLDER_TYPE VARCHAR(4) DEFAULT NULL COMMENT '投资人类型',
    INVEST_AMOUNT DECIMAL(30,8) DEFAULT NULL COMMENT '投资金额（元）',
    INVEST_RATIO DECIMAL(30,8) DEFAULT NULL COMMENT '投资比例',
    TWO_HOLDER_NAME VARCHAR(50) DEFAULT NULL COMMENT '二级投资人名称',
    TWO_HOLDER_TYPE VARCHAR(4) DEFAULT NULL COMMENT '二级投资人类型',
    TWO_INVEST_AMOUNT DECIMAL(30,8) DEFAULT NULL COMMENT '二级投资人投资金额（元）',
    TWO_INVEST_RATIO DECIMAL(30,8) DEFAULT NULL COMMENT '二级投资人投资比例',
    PROD_SHARE DECIMAL(30,8) DEFAULT NULL COMMENT '产品份额',
    HOLDER_SHARE DECIMAL(30,8) DEFAULT NULL COMMENT '投资人份额',
    REMARK VARCHAR(1000) DEFAULT NULL COMMENT '备注',
    STATUS VARCHAR(10) DEFAULT NULL COMMENT '数据状态',
    CHB_SUBMIT_DEADLINE TIMESTAMP(6) DEFAULT NULL COMMENT '中债报送截止日',
    STATUS_DATE DATE DEFAULT NULL COMMENT '数据日期',
    SUBMIT_TIME TIMESTAMP(6) DEFAULT NULL COMMENT '报送时间',
    SUMIT_SEQ VARCHAR(50) DEFAULT NULL COMMENT '报送流水号',
    SEND_STATUS VARCHAR(2) DEFAULT NULL COMMENT '报送状态',
    SUBMIT_FEEDBACK_STATUS VARCHAR(50) DEFAULT NULL COMMENT '反馈状态',
    SUBMIT_FEEDBACK_MSG VARCHAR(600) DEFAULT NULL COMMENT '报送反馈消息',
    CREATE_USER VARCHAR(20) DEFAULT NULL COMMENT '创建人',
    ORG_CODE VARCHAR(20) DEFAULT NULL COMMENT '机构代码',
    CREATE_DEPT VARCHAR(20) DEFAULT NULL COMMENT '创建部门',
    CREATE_TIME TIMESTAMP(6) DEFAULT NULL COMMENT '创建时间',
    UPDATE_USER VARCHAR(20) DEFAULT NULL COMMENT '更新人',
    UPDATE_TIME TIMESTAMP(6) DEFAULT NULL COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT'委托人明细数据登记表';


